// Plain data from the extension (generated by `npm run prep`). Safe to import from server and client components.
import data from '@/data/footlit.json';

export type Mood = 'applause' | 'farewell' | 'alarm';
export type EventDef = (typeof data.events)[number];
export type ThemeMeta = (typeof data.themes)[number];

export const EVENTS: EventDef[] = data.events;
export const GROUPS = data.groups;
export const THEMES: ThemeMeta[] = data.themes;
export const MOODS = data.moods as Record<Mood, { label: string; blurb: string }>;
export const VERSION: string = data.version;
export const DOWNLOADS = data.downloads as { chrome?: { file: string; kb: number }; firefox?: { file: string; kb: number } };
export const EVENT_BY_ID = Object.fromEntries(EVENTS.map((e) => [e.id, e])) as Record<string, EventDef>;
